/attempt #71

### 🛠️ Production Implementation & Technical Verification

1. **Root Cause Analysis & Architectural Fault Line**:
- **Missing Allowlist Verification (`src/allowlist/index.ts`)**: `src/allowlist/index.ts` houses query AST normalization, SQL statement sanitation (stripping trailing semicolons), admin bypass validation, and rejected query persistence. However, zero Vitest test harness existed for this critical security subsystem (`src/allowlist/index.test.ts` was completely absent).
- **LiteREST Edge-Case Gaps (`src/literest/index.ts`)**: While `src/literest/index.test.ts` tested standard queries, it lacked negative edge-case test coverage explicitly specified by the maintainer: handling fake/non-existent tables, missing/empty table names, `-1` primary key inputs, and `null` filter parameters.

---

2. **Production-Grade Implementation Source Code**:

### Production Source (`src/allowlist/index.test.ts`)
```typescript
import { describe, it, expect, vi, beforeEach } from 'vitest'
import { isQueryAllowed } from './index'
import type { DataSource } from '../types'
import type { StarbaseDBConfiguration } from '../handler'

describe('Allowlist Engine Test Suite', () => {
    let mockDataSource: DataSource
    let mockConfig: StarbaseDBConfiguration

    beforeEach(() => {
        vi.clearAllMocks()
        mockDataSource = {
            source: 'external',
            external: { dialect: 'sqlite' } as any,
            rpc: {
                executeQuery: vi.fn(),
            },
        } as any

        mockConfig = {
            outerbaseApiKey: 'test-key',
            role: 'user',
            features: { allowlist: true, rls: true, rest: true },
        }
    })

    it('should immediately permit queries when allowlist feature is disabled', async () => {
        const allowed = await isQueryAllowed({
            sql: 'SELECT * FROM secret_table',
            isEnabled: false,
            dataSource: mockDataSource,
            config: mockConfig,
        })
        expect(allowed).toBe(true)
        expect(mockDataSource.rpc.executeQuery).not.toHaveBeenCalled()
    })

    it('should bypass allowlist checks for users with admin role', async () => {
        const adminConfig: StarbaseDBConfiguration = { ...mockConfig, role: 'admin' }
        const allowed = await isQueryAllowed({
            sql: 'DROP TABLE production_db',
            isEnabled: true,
            dataSource: mockDataSource,
            config: adminConfig,
        })
        expect(allowed).toBe(true)
        expect(mockDataSource.rpc.executeQuery).not.toHaveBeenCalled()
    })

    it('should permit an exact matching normalized SQL query', async () => {
        vi.mocked(mockDataSource.rpc.executeQuery).mockResolvedValueOnce([
            { source: 'external', sql_statement: 'SELECT id, name FROM users WHERE id = 1;' }
        ] as any)

        const allowed = await isQueryAllowed({
            sql: 'SELECT id, name FROM users WHERE id = 1',
            isEnabled: true,
            dataSource: mockDataSource,
            config: mockConfig,
        })
        expect(allowed).toBe(true)
    })

    it('should reject unapproved queries and record audit in tmp_allowlist_rejections', async () => {
        // Allowlist contains only SELECT
        vi.mocked(mockDataSource.rpc.executeQuery)
            .mockResolvedValueOnce([
                { source: 'external', sql_statement: 'SELECT id FROM users' }
            ] as any) // loadAllowlist
            .mockResolvedValueOnce([] as any) // addRejectedQuery

        await expect(isQueryAllowed({
            sql: 'DELETE FROM users WHERE id = 5',
            isEnabled: true,
            dataSource: mockDataSource,
            config: mockConfig,
        })).rejects.toThrow('Query not allowed')

        // Verify rejected query was written to tmp_allowlist_rejections
        expect(mockDataSource.rpc.executeQuery).toHaveBeenCalledWith(expect.objectContaining({
            params: ['DELETE FROM users WHERE id = 5', 'external']
        }))
    })

    it('should throw an error if SQL string is empty or missing', async () => {
        await expect(isQueryAllowed({
            sql: '',
            isEnabled: true,
            dataSource: mockDataSource,
            config: mockConfig,
        })).rejects.toThrow('No SQL provided for allowlist check')
    })
})
```

